"""Context-preserving terminal commitments for the synthetic NdFeB mission.

The host supplies an authenticated terminal event, registered executable models,
and the complete evidence snapshot. Policy citations and prediction coordinates
are declarations, not substitutes for those bindings. A nomination is assessable
without asserting that the nominated material already satisfies every criterion.
This module never repairs a scientific model, an evidence ID, or an outcome.
"""

from __future__ import annotations

import copy
import hashlib
import json
import math
import re
from datetime import datetime

from .contracts import digest

VERSION = "ndfeb-terminal-commitment-v2"
STATUSES = {"recommend_candidate", "retain_reference", "withhold"}
COORDINATES = {"requested_conditions", "indicated_conditions"}
_IDENTITY_KEYS = {
    "recommendation_status", "candidate", "reference", "model_id", "source_sha256",
    "artifact_sha256s", "prediction_coordinates", "candidate_coordinates", "temperature_c",
    "requested_temperature_c", "committed_at", "evidence_sha256", "evidence_cutoff",
    "origin", "lot_id", "fixed_other_process_fields",
    "fixed_other_process_fields_retain_public_supported_recipe",
}
_SCOPE_KEYS = ("scope", "scope_and_limitations", "scope_and_limits", "limitations")
_FIXED_RECIPE = {
    "route": "mqu_f_sps", "process_stage": "initial_sps", "post_treatment": "none",
    "pressure_mpa": 50, "hold_time_s": 30, "heating_rate_c_min": 100,
    "mass_g": 15, "diameter_mm": 20, "die_material": "graphite",
    "field_alignment": "none", "allow_source_transfer": True,
}
DEFAULT_MISSION = {
    "reference_temperature_c": 700,
    "candidate_coordinates": "requested_conditions",
    "temperature_domain_c": [550, 800],
    "origin": "synthetic", "lot_id": "synthetic-melt-spun-lot",
    "fixed_recipe": _FIXED_RECIPE,
}


class CommitmentError(ValueError):
    """A structural, identity, or provenance conflict that needs policy repair."""


def _text(value, name):
    if not isinstance(value, str) or not value.strip():
        raise CommitmentError(f"{name} must be a nonempty string")
    return value


def _finite(value, name):
    if isinstance(value, bool) or not isinstance(value, (float, int)) or not math.isfinite(value):
        raise CommitmentError(f"{name} must be a finite number")
    return float(value)


def _timestamp(value, name):
    try:
        result = datetime.fromisoformat(value)
    except (TypeError, ValueError) as exc:
        raise CommitmentError(f"{name} requires an ISO timestamp") from exc
    if result.tzinfo is None:
        raise CommitmentError(f"{name} requires a timezone")
    return result


def _hash(value, name):
    if not isinstance(value, str) or re.fullmatch("[a-f0-9]{64}", value) is None:
        raise CommitmentError(f"{name} requires a SHA256")
    return value


def _pairs(items):
    result = {}
    for key, value in items:
        if key in result and key in _IDENTITY_KEYS:
            raise CommitmentError(f"duplicate identity field: {key}")
        result[key] = value
    return result


def _walk(value, path=()):
    if isinstance(value, dict):
        yield path, value
        for key, child in value.items():
            yield from _walk(child, (*path, key))
    elif isinstance(value, list):
        for index, child in enumerate(value):
            yield from _walk(child, (*path, index))


def parse_commitment(rationale):
    """Find one explicit nomination while retaining all outer context.

    JSON embedded in prose or fences is accepted. One narrowly defined syntax
    recovery accepts continued object members after an early closing brace (an
    actual historical failure); it changes no keys or values and is recorded.
    Conflicting or independent nominations and duplicate identity keys are
    rejected; identical enclosing declarations represent one nomination.
    """
    if isinstance(rationale, dict):
        rationale = json.dumps(rationale, allow_nan=False, ensure_ascii=False)
    raw = _text(rationale, "rationale")
    decoder = json.JSONDecoder(object_pairs_hook=_pairs)
    documents, recoveries = [], []
    index = 0
    while index < len(raw):
        if raw[index] != "{":
            index += 1
            continue
        try:
            document, length = decoder.raw_decode(raw[index:])
        except json.JSONDecodeError:
            index += 1
            continue
        end = index + length
        tail = raw[end:].lstrip()
        if tail.startswith((', "', ',\n')):
            continued = "{" + tail[1:].lstrip()
            try:
                members, n = decoder.raw_decode(continued)
            except json.JSONDecodeError:
                members = None
            if isinstance(members, dict) and not continued[n:].strip():
                overlap = set(document) & set(members)
                if overlap:
                    raise CommitmentError("continued object repeats fields: " + ", ".join(sorted(overlap)))
                document = {**document, **members}
                recoveries.append({"kind": "continued_object_members_after_early_close", "offset": end})
                end = len(raw)
        documents.append(document)
        index = end
    nominations = [(i, path, obj) for i, doc in enumerate(documents)
                   for path, obj in _walk(doc) if "recommendation_status" in obj]
    if not nominations:
        raise CommitmentError("expected exactly one explicit final recommendation object")
    # Repeating the same declaration in an enclosing envelope is not a second
    # decision. Only one ancestry chain is allowed; conflicting identities below
    # still fail, and sibling/independent nominations remain ambiguous.
    doc_index, path, _nomination = max(nominations, key=lambda item: len(item[1]))
    if any(i != doc_index or path[:len(p)] != p for i, p, _ in nominations):
        raise CommitmentError("expected exactly one explicit final recommendation object")
    # Identity declarations at enclosing levels cannot contradict the inner object.
    ancestor = documents[doc_index]
    layers = [ancestor]
    for segment in path:
        ancestor = ancestor[segment]
        if isinstance(ancestor, dict):
            layers.append(ancestor)
    for key in _IDENTITY_KEYS:
        values = [layer[key] for layer in layers if key in layer]
        if values and any(value != values[0] for value in values[1:]):
            raise CommitmentError(f"conflicting enclosing {key} declarations")
    merged = {}
    for layer in layers:
        merged.update(layer)
    citations = [layer["evidence_ids"] for layer in layers if "evidence_ids" in layer]
    if len(citations) > 1:
        merged["evidence_ids"] = {"enclosing_declarations": citations}
    scopes = []
    for layer in layers:
        for key in _SCOPE_KEYS:
            if key in layer:
                value = layer[key]
                if isinstance(value, str) and value.strip():
                    scopes.append(value)
                elif isinstance(value, list) and value and all(isinstance(v, str) and v.strip() for v in value):
                    scopes.extend(value)
                else:
                    raise CommitmentError(f"{key} requires text or a nonempty list of text")
    return {
        "nomination": copy.deepcopy(merged), "documents": documents,
        "nomination_path": [doc_index, *path], "raw_rationale": raw,
        "scope": "\n".join(dict.fromkeys(scopes)) if scopes else raw,
        "scope_origin": "explicit_enclosing_scope" if scopes else "complete_policy_rationale",
        "syntax_recoveries": recoveries,
    }


def _unique_declaration(objects, key, default=None):
    values = [obj[key] for obj in objects if isinstance(obj, dict) and key in obj]
    if values and any(value != values[0] for value in values[1:]):
        raise CommitmentError(f"conflicting {key} declarations")
    return values[0] if values else default


def _recipe(value, name, mission):
    if not isinstance(value, dict):
        raise CommitmentError(f"{name} requires an explicit recipe object")
    allowed = {"temperature_c", "requested_temperature_c", "coordinates", *mission["fixed_recipe"]}
    if set(value) - allowed:
        raise CommitmentError(f"{name} has unsupported recipe fields: {sorted(set(value) - allowed)}")
    temps = [value[k] for k in ("temperature_c", "requested_temperature_c") if k in value]
    if not temps or any(t != temps[0] for t in temps[1:]):
        raise CommitmentError(f"{name} needs one unambiguous temperature")
    temperature = _finite(temps[0], name + ".temperature_c")
    if not mission["temperature_domain_c"][0] <= temperature <= mission["temperature_domain_c"][1]:
        raise CommitmentError(f"{name} is outside the supported temperature domain")
    if value.get("coordinates", mission["candidate_coordinates"]) != mission["candidate_coordinates"]:
        raise CommitmentError(f"{name} coordinates conflict with requested intervention coordinates")
    for key, supplied in value.items():
        if key in mission["fixed_recipe"] and supplied != mission["fixed_recipe"][key]:
            raise CommitmentError(f"{name} changes fixed recipe field: {key}")
    return {"temperature_c": temperature}


def _coordinate_declaration(value):
    if isinstance(value, str) and value in COORDINATES:
        return {"input": value, "status": "explicit", "raw": value}
    if isinstance(value, str):
        leading = value.split(";", 1)[0].strip()
        mentioned = [coordinate for coordinate in COORDINATES if coordinate in value]
        if leading in COORDINATES and len(mentioned) == 1:
            return {"input": leading, "status": "explicit_with_qualification", "raw": value}
        return {"input": None, "status": "ambiguous_or_unrecognized", "raw": value}
    if isinstance(value, dict):
        declared = _unique_declaration([value], "input", value.get("input_coordinates"))
        if "input" in value and "input_coordinates" in value and value["input"] != value["input_coordinates"]:
            raise CommitmentError("conflicting prediction input coordinate declarations")
        if isinstance(declared, str) and declared in COORDINATES:
            return {"input": declared, "status": "explicit_structured", "raw": copy.deepcopy(value)}
    return {"input": None, "status": "not_declared", "raw": copy.deepcopy(value)}


def resolve_citations(value, prior_evidence):
    """Expand explicit lists, grouped IDs, delivery IDs and finite index ranges.

    Nonexistent IDs, ellipses and descriptive fragments remain unresolved. The
    resolver never fuzzy-matches IDs or treats duplicates as new observations.
    """
    visible = {row["evidence_id"] for row in prior_evidence}
    deliveries = {}
    for row in prior_evidence:
        if row.get("delivery_id"):
            deliveries.setdefault(row["delivery_id"], []).append(row["evidence_id"])
    leaves = []

    def flatten(node):
        if isinstance(node, dict):
            for child in node.values():
                flatten(child)
        elif isinstance(node, list):
            for child in node:
                flatten(child)
        else:
            leaves.append(node)

    flatten(value if value is not None else [])
    expanded, unresolved, resolutions = [], [], []
    for leaf in leaves:
        matches = []
        if isinstance(leaf, str):
            text = leaf.strip()
            if text in visible:
                matches = [text]
            elif text.removeprefix("evidence:") in deliveries:
                matches = deliveries[text.removeprefix("evidence:")]
            else:
                # Braced lists may carry a parenthetical label, but not ellipses.
                match = re.fullmatch(r"(evidence:[^:{}\s]+):\{([^{}]+)\}(?:\s+\([^\n]*\))?", text)
                simple_range = re.fullmatch(r"(evidence:[^:{}\s]+):(\d+)(?:\.\.|-)(\d+)", text)
                if match:
                    prefix, body = match.groups()
                    indices = []
                    for item in body.split(","):
                        part = re.fullmatch(r"\s*(\d+)(?:(?:\.\.|-)(\d+))?\s*", item)
                        if part is None:
                            indices = None
                            break
                        start, end = int(part[1]), int(part[2] or part[1])
                        if end < start or end - start > len(visible):
                            indices = None
                            break
                        indices.extend(range(start, end + 1))
                    if indices is not None:
                        matches = [f"{prefix}:{i}" for i in indices]
                elif simple_range:
                    prefix, start, end = simple_range.groups()
                    if 0 <= int(end) - int(start) <= len(visible):
                        matches = [f"{prefix}:{i}" for i in range(int(start), int(end) + 1)]
        if not matches or any(item not in visible for item in matches):
            unresolved.append(copy.deepcopy(leaf))
        else:
            expanded.extend(matches)
            resolutions.append({"citation": leaf, "evidence_ids": list(matches)})
    return {
        "evidence_ids": sorted(set(expanded)), "unresolved": unresolved,
        "duplicate_reference_count": len(expanded) - len(set(expanded)),
        "resolutions": resolutions, "raw": copy.deepcopy(value),
        "all_resolved": not unresolved,
    }


def normalize_commitment(rationale, *, terminal, registered_models, prior_evidence, mission=None):
    """Bind one live terminal commitment; historical replays use the same API.

    ``terminal`` is the original host ``record_decision`` return. Models are the
    host's ``campaign.models()`` records, including source text. The caller must
    authenticate the host store/blobs; this pure function checks consistency and
    source hashes but does not claim cryptographic authenticity of supplied data.
    ``mission`` may add fields, but cannot change this module's synthetic recipe.
    """
    configured = copy.deepcopy(DEFAULT_MISSION)
    if mission is not None:
        for key, value in DEFAULT_MISSION.items():
            if key in mission and mission[key] != value:
                raise CommitmentError(f"mission changes this version's fixed {key}")
    parsed = parse_commitment(rationale)
    raw = parsed["nomination"]
    if terminal.get("decision") != "stop":
        raise CommitmentError("a host terminal stop event is required")
    if parsed["raw_rationale"] != terminal.get("rationale"):
        raise CommitmentError("rationale differs from the original terminal event")
    committed_at = terminal.get("recorded_at")
    timestamp = _timestamp(committed_at, "terminal.recorded_at")
    ids = [row["evidence_id"] for row in prior_evidence]
    if len(ids) != len(set(ids)) or any(not isinstance(item, str) or not item for item in ids):
        raise CommitmentError("the complete evidence cutoff contains invalid/duplicate IDs")
    if digest(prior_evidence) != terminal.get("evidence_sha256"):
        raise CommitmentError("released evidence changed after the terminal commitment")
    if terminal.get("evidence_ids") != ids:
        raise CommitmentError("terminal evidence IDs do not match the complete ordered cutoff")
    for row in prior_evidence:
        if row.get("released_at") and _timestamp(row["released_at"], "evidence.released_at") > timestamp:
            raise CommitmentError("evidence was released after the commitment")
    status = raw.get("recommendation_status")
    if status not in STATUSES:
        raise CommitmentError("an explicit recognized recommendation_status is required")
    candidate = None
    if status == "recommend_candidate":
        candidate = _recipe(raw.get("candidate"), "candidate", configured)
        if candidate["temperature_c"] >= configured["reference_temperature_c"]:
            raise CommitmentError("candidate must be below the reference; self-comparison is ineligible")
    elif raw.get("candidate") is not None:
        raise CommitmentError("withhold/retain_reference must not also nominate a candidate")
    reference = _recipe(raw.get("reference", {"temperature_c": configured["reference_temperature_c"]}),
                        "reference", configured)
    if reference["temperature_c"] != configured["reference_temperature_c"]:
        raise CommitmentError("reference contradicts the predeclared mission")
    if raw.get("candidate_coordinates", configured["candidate_coordinates"]) != configured["candidate_coordinates"]:
        raise CommitmentError("candidate coordinates contradict the requested-condition mission")
    for key in ("origin", "lot_id"):
        if key in raw and raw[key] != configured[key]:
            raise CommitmentError(f"nomination changes mission {key}")
    for key in ("fixed_other_process_fields", "fixed_other_process_fields_retain_public_supported_recipe"):
        if key not in raw:
            continue
        fields = raw[key]
        if not isinstance(fields, dict):
            raise CommitmentError(f"{key} requires an object")
        fixed = {**configured["fixed_recipe"], "origin": configured["origin"], "lot_id": configured["lot_id"]}
        if any(k not in fixed or v != fixed[k] for k, v in fields.items()):
            raise CommitmentError("nomination changes an unsupported fixed recipe field")
    # Resolve explicit executable aliases in outer context too, without semantic NLP.
    documents = parsed["documents"]
    declarations = [raw]
    for doc in documents:
        for _, obj in _walk(doc):
            for key in ("selected_model", "active_model"):
                if key in obj:
                    declarations.append(obj[key])
            if isinstance(obj.get("supporting_evidence"), dict):
                declarations.append(obj["supporting_evidence"].get("model"))
    selected = _unique_declaration(declarations, "model_id", terminal.get("model_id"))
    _text(selected, "selected model_id")
    registry = list(registered_models.values()) if isinstance(registered_models, dict) else registered_models
    matching = [model for model in registry if model.get("model_id") == selected]
    if len(matching) != 1:
        raise CommitmentError("selected model must identify exactly one registered executable")
    model = matching[0]
    source_hash = _hash(model.get("source_sha256"), "registered source_sha256")
    source = _text(model.get("source"), "registered executable source")
    if hashlib.sha256(source.encode()).hexdigest() != source_hash:
        raise CommitmentError("registered executable source hash mismatch")
    artifacts = model.get("artifact_sha256s", [])
    if not isinstance(artifacts, list) or len(artifacts) != len(set(artifacts)):
        raise CommitmentError("registered model artifact bindings must be a unique list")
    for value in artifacts:
        _hash(value, "registered artifact_sha256s item")
    if _timestamp(model.get("adopted_at"), "model.adopted_at") > timestamp:
        raise CommitmentError("selected model was registered after the terminal event")
    if _unique_declaration(declarations, "source_sha256", source_hash) != source_hash:
        raise CommitmentError("declared executable source differs from selected registered model")
    if _unique_declaration(declarations, "artifact_sha256s", artifacts) != artifacts:
        raise CommitmentError("declared artifact bindings differ from selected registered model")
    for declaration in declarations:
        if (isinstance(declaration, dict) and "bound_artifact" in declaration
                and declaration["bound_artifact"] not in artifacts):
            raise CommitmentError("declared model artifact is not bound to selected model")
    if raw.get("committed_at", committed_at) != committed_at:
        raise CommitmentError("declared commitment time differs from host event")
    citations = resolve_citations(raw.get("evidence_ids"), prior_evidence)
    coordinate = _coordinate_declaration(raw.get("prediction_coordinates"))
    cutoff_claims = []
    for doc in documents:
        for path, obj in _walk(doc):
            for key in ("released_evidence_sha256", "evidence_sha256"):
                if key in obj and obj[key] != terminal["evidence_sha256"]:
                    cutoff_claims.append({"path": [*path, key], "declared": obj[key],
                                          "actual": terminal["evidence_sha256"]})
            if "evidence_cutoff" in obj:
                cutoff = obj["evidence_cutoff"]
                actual = {"ids": ids, "sha256": terminal["evidence_sha256"], "count": len(ids)}
                if not isinstance(cutoff, dict) or any(
                    key in cutoff and cutoff[key] != actual[key] for key in actual
                ) or not any(key in cutoff for key in actual):
                    cutoff_claims.append({"path": [*path, "evidence_cutoff"],
                                          "declared": cutoff, "actual": actual})
    result = {
        "schema": VERSION, "recommendation_status": status,
        "candidate": candidate, "reference": reference,
        "candidate_coordinates": configured["candidate_coordinates"],
        "fixed_recipe": configured["fixed_recipe"], "origin": configured["origin"],
        "lot_id": configured["lot_id"], "scope": parsed["scope"],
        "model_id": selected, "source_sha256": source_hash, "artifact_sha256s": list(artifacts),
        "binding_origin": "policy_explicit" if any(isinstance(d, dict) and "model_id" in d for d in declarations)
                          else "host_captured_active_at_terminal",
        "terminal_active_model_id": terminal.get("model_id"), "committed_at": committed_at,
        "terminal_sha256": digest(terminal), "registered_model_sha256": digest(model),
        "evidence_ids": citations["evidence_ids"],
        "evidence_cutoff": {"ids": ids, "sha256": terminal["evidence_sha256"], "count": len(ids)},
        "prediction_coordinates": coordinate["input"], "coordinate_declaration": coordinate,
        "citation_resolution": citations, "declared_cutoff_conflicts": cutoff_claims,
        "validity": {"nomination_assessable": status == "recommend_candidate",
                     "decision_assessable": True, "source_content_verified": True,
                     "cutoff_consistency_verified": True,
                     "citations_resolved": citations["all_resolved"],
                     "declared_cutoff_consistent": not cutoff_claims,
                     "prediction_input_coordinates_declared": coordinate["input"] is not None,
                     "forecast_implementation_verified": False,
                     "attainment_verified": False, "external_record_authenticity_verified": False},
        "interpretation": "A nominated candidate receives independent assessment; nomination is not verified advancement.",
        "normalization": parsed,
        "reference_origin": "policy_explicit" if "reference" in raw else "predeclared_public_mission",
        "mission_sha256": digest(configured),
    }
    # JSON finiteness also rejects NaN/Infinity hidden in arbitrary extra context.
    json.dumps(result, allow_nan=False)
    return copy.deepcopy(result)


def validate_commitment(commitment, *, terminal, registered_models, prior_evidence, mission=None):
    """Reconstruct a normalized record and reject post-binding modifications."""
    if not isinstance(commitment, dict) or commitment.get("schema") != VERSION:
        raise CommitmentError("expected a normalized v2 commitment")
    expected = normalize_commitment(commitment.get("normalization", {}).get("raw_rationale"),
                                    terminal=terminal, registered_models=registered_models,
                                    prior_evidence=prior_evidence, mission=mission)
    if expected != commitment:
        raise CommitmentError("normalized commitment differs from authenticated inputs")
    return copy.deepcopy(commitment)
